  | {
      readonly kind: 'tool_approval_requested';
      readonly executionId: ExecutionId;
      readonly actionId: ActionId;
      readonly request: unknown;
    }
  | {
      readonly kind: 'ask_user_requested';
      readonly executionId: ExecutionId;
      readonly actionId: ActionId;
